// Negative fixtures perturb generated bytes, then pin the new hash; positive execution never uses these faults.
export function cleanupRejectionArtifact(bytes: Uint8Array): Uint8Array<ArrayBuffer> {
  const source = new TextDecoder().decode(bytes);
  const owned = 'logger.info("remote cleaned");';
  const final = "return { success: true, data: { async cleanup() {";
  if (source.split(owned).length !== 2 || source.split(final).length !== 2) throw new Error("cleanup-fixture-marker-mismatch");
  return new TextEncoder().encode(
    source
      .replace(owned, 'logger.warn("remote cleanup rejection attempted"); throw new Error("SECRET_ERROR_SENTINEL");')
      .replace(final, `${final}\nlogger.info("remote final cleanup attempted");`),
  );
}
